INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001500081','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001500081","revision":1,"targetId":"80000000-0000-4000-8000-000000015008","prompt":"Nach mehrfacher Kontrolle ist sie überzeugt, dass die Zahlen stimmen. Mit welchem Wort beschreibt man ihre Gewissheit?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"This time the word expresses confidence rather than physical protection.","de":"Diesmal geht es um Gewissheit, nicht um Schutz."},"options":[{"id":"0","text":"Eile"},{"id":"1","text":"Angst"},{"id":"2","text":"Begeisterung"},{"id":"3","text":"Sicherheit"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Mit großer Sicherheit expresses strong certainty.","de":"Mit großer Sicherheit drückt hohe Gewissheit aus."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie weiß es mit großer Sicherheit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2146 (6c3aeb127b72b22d69adb9a373f2983ccc7bdb6eba320fcf5d418054a74ace58), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
