INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001500161','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001500161","revision":1,"targetId":"80000000-0000-4000-8000-000000015016","prompt":"Ein kurzer Ton zeigt an, dass die Türen gleich schließen. Was ist dieser Ton?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The sound conveys information without spoken words.","de":"Der Ton vermittelt eine Information ohne gesprochene Worte."},"options":[{"id":"0","text":"Gespräch"},{"id":"1","text":"Signal"},{"id":"2","text":"Fehler"},{"id":"3","text":"Gerücht"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"An acoustic sign announcing closing doors is a signal.","de":"Ein akustisches Zeichen für schließende Türen ist ein Signal."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Ton ist ein Signal.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2154 (b4709f38cecaf84532d4e663c4d66308c2ab0edefb91e410f506bd6bdc738235), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
