INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001500171','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001500171","revision":1,"targetId":"80000000-0000-4000-8000-000000015017","prompt":"Welche Aussage bedeutet, dass eine Maßnahme keinen erkennbaren Zweck hat?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"Look for the statement about purpose, not time, name or money.","de":"Gesucht ist die Aussage über den Zweck, nicht über Zeit, Name oder Geld."},"options":[{"id":"0","text":"Die Maßnahme hat keinen Termin."},{"id":"1","text":"Die Maßnahme hat keinen Namen."},{"id":"2","text":"Die Maßnahme hat keinen Sinn."},{"id":"3","text":"Die Maßnahme hat keinen Preis."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Hat keinen Sinn means has no meaningful purpose.","de":"Hat keinen Sinn bedeutet, dass kein sinnvoller Zweck erkennbar ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Maßnahme hat keinen Sinn.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2155 (cf3223893857efb22ab7ba8a0e99141427efc6e013e501f54eef4207e4926e6a), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
