INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001500181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001500181","revision":1,"targetId":"80000000-0000-4000-8000-000000015018","prompt":"Auf einer Kinokarte steht „Reihe 4, Platz 8“. Was bezeichnet Platz 8?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The ticket identifies where the viewer should sit.","de":"Die Karte zeigt, wo die Person sitzen soll."},"options":[{"id":"0","text":"Ausgang"},{"id":"1","text":"Leinwand"},{"id":"2","text":"Kasse"},{"id":"3","text":"Sitz"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"A numbered cinema place is a seat.","de":"Ein nummerierter Kinoplatz ist ein Sitz."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Platz 8 bezeichnet einen Sitz im Kino.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2157 (a130385795c7cf4617eb47bb193c753202e9d9363494a35a30dcda06120d22d2), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
