INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510040','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510040","revision":1,"targetId":"80000000-0000-4000-8000-000000015104","prompt":"Nur bis Samstag gibt es die Jacke als ___ für 30 statt 50 Euro.","instruction":{"en":"Choose the word that correctly completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz richtig ergänzt."},"hint":{"en":"The shop temporarily reduces the price for shoppers.","de":"Das Geschäft senkt den Preis für kurze Zeit."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Leihgabe"},{"id":"1","text":"Gutschein"},{"id":"2","text":"Sonderangebot"},{"id":"3","text":"Bestellung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"A temporary reduced-price sale is a Sonderangebot.","de":"Ein zeitlich begrenztes günstiges Angebot ist ein Sonderangebot."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nur bis Samstag gibt es die Jacke als Sonderangebot für 30 statt 50 Euro.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2166 (9395400d2d929fedbffd0207584e9cad58b5de600cbe1a6643522ee58ef8c44d), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
