INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510050','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510050","revision":1,"targetId":"80000000-0000-4000-8000-000000015105","prompt":"Für die Großbestellung hat der Lieferant uns einen ___ angeboten.","instruction":{"en":"Choose the word that correctly completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz richtig ergänzt."},"hint":{"en":"A large order receives a price different from the standard one.","de":"Eine große Bestellung erhält einen vom Normalpreis abweichenden Preis."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Liefertermin"},{"id":"1","text":"Sonderpreis"},{"id":"2","text":"Mindestlohn"},{"id":"3","text":"Lagerplatz"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"A specially negotiated rate for a bulk order is a Sonderpreis.","de":"Ein für eine Großbestellung vereinbarter Preis ist ein Sonderpreis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Großbestellung hat der Lieferant uns einen Sonderpreis angeboten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2167 (bf512b97feafa1b51adeae71163a0069d01eddc629ea3f7166266835af1a1f0f), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
