INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510051','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510051","revision":1,"targetId":"80000000-0000-4000-8000-000000015105","prompt":"Ein Stammkunde zahlt für dasselbe Produkt weniger als den regulären Verkaufspreis. Wie heißt dieser individuell vereinbarte Preis?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The shop agrees a different price for this customer.","de":"Das Geschäft vereinbart für diesen Kunden einen anderen Preis."},"options":[{"id":"0","text":"Pfand"},{"id":"1","text":"Steuersatz"},{"id":"2","text":"Rückgabefrist"},{"id":"3","text":"Sonderpreis"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"An individually agreed reduced price is a Sonderpreis.","de":"Ein individuell vereinbarter günstiger Preis ist ein Sonderpreis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Kunde erhält einen Sonderpreis.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2167 (bf512b97feafa1b51adeae71163a0069d01eddc629ea3f7166266835af1a1f0f), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
