INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510061','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510061","revision":1,"targetId":"80000000-0000-4000-8000-000000015106","prompt":"Ein Partner unterliegt anderen internen Regeln als die übrigen Partner. Wie nennt man seine besondere Stellung?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"He has an exceptional position within the group.","de":"Er hat innerhalb der Gruppe eine Ausnahmestellung."},"options":[{"id":"0","text":"Lieferadresse"},{"id":"1","text":"Rabattcode"},{"id":"2","text":"Sonderstatus"},{"id":"3","text":"Arbeitszeit"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Different internal treatment can indicate a Sonderstatus.","de":"Abweichende interne Regeln können einen Sonderstatus kennzeichnen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Partner hat einen Sonderstatus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2168 (87043d8b20d246d7a0a8c44cb28788b3a5737c218b2b9f6ae3262591f3d0c3dc), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
