INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510151","revision":1,"targetId":"80000000-0000-4000-8000-000000015115","prompt":"Ein Team in einer Klinik hilft bei Fragen zur häuslichen Versorgung und zu Hilfsangeboten. Welche Stelle ist gemeint?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The team advises on support beyond medical treatment.","de":"Das Team berät zu Hilfen außerhalb der medizinischen Behandlung."},"options":[{"id":"0","text":"Empfang"},{"id":"1","text":"Küche"},{"id":"2","text":"Sozialdienst"},{"id":"3","text":"Technikabteilung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Social support planning is a role of the hospital Sozialdienst.","de":"Die Beratung zu sozialen Hilfen gehört zum Sozialdienst."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Team gehört zum Sozialdienst.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2180 (3aae94634944f31a0da23733f5bf750ac156c3a7229e367c0c02c25781a2fa53), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
